entries[3869] = { ["name"] = "Pläne: Schattensichelaxt", ["text"] = "Benutzen: Lehrt Euch die Herstellung einer Schattensichelaxt.\nBenötigt Klassische Schmiedekunst (200)\nVerkaufspreis:\nSchattensichelaxt\nWird beim Anlegen gebunden\nZweihändig Axt\n5 - 10 Schaden Geschwindigkeit 3.60\n(2.1 Schaden pro Sekunde)\n+4 Stärke\n+4 Ausdauer\nHaltbarkeit 85 / 85\nVerkaufspreis:\nBenötigt Stahlbarren (10), Citrin (2), Schattenöl (2)\nOptionale Reagenzien: [] (#49)" }
