entries[4392] = { ["name"] = "Hochentwickelte Zielattrappe", ["text"] = "Benutzen: Lässt eine Zielattrappe auf den Boden fallen, die in der Nähe befindliche Monster dazu bringt, sie anzugreifen. Die Attrappe bleibt bis zu ihrer Zerstörung aktiv, maximal jedoch für 15 Sekunden. (2 Min Abklingzeit)\nBenötigt Klassische Ingenieurskunst (185)\nVerkaufspreis:" }
