entries[4395] = { ["name"] = "Goblinlandmine", ["text"] = "Benutzen: Platziert die Goblinlandmine auf dem Boden. Sie explodiert, sobald eine feindliche Kreatur an ihr vorbeigeht, und fügt ihr 24 Feuerschaden zu. Die Mine ist 1 Min. lang aktiv. (1 Min Abklingzeit)\nBenötigt Klassische Ingenieurskunst (195)\nVerkaufspreis:" }
