entries[4405] = { ["name"] = "Kunstloses Zielfernrohr", ["text"] = "Benutzen: Bringt dauerhaft ein Zielfernrohr an einem Bogen oder einer Schusswaffe an, das den damit verursachten Schaden um 1 erhöht. Kann nicht auf Gegenstände über Stufe 0 angewandt werden.\nVerkaufspreis:" }
entries[4406] = { ["name"] = "Standardzielfernrohr", ["text"] = "Benutzen: Bringt dauerhaft ein Zielfernrohr an einem Bogen oder einer Schusswaffe an, das den damit verursachten Schaden um 1 erhöht. Kann nicht auf Gegenstände über Stufe 0 angewandt werden.\nVerkaufspreis:" }
entries[4407] = { ["name"] = "Genaues Zielfernrohr", ["text"] = "Benutzen: Bringt dauerhaft ein Zielfernrohr an einem Bogen oder einer Schusswaffe an, das den damit verursachten Schaden um 2 erhöht.\n\nDurch das Anbringen des Fernrohrs an einer Distanzwaffe wird diese seelengebunden. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nVerkaufspreis:" }
entries[4408] = { ["name"] = "Bauplan: Kasten mit mechanischem Eichhörnchen", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines Kastens mit mechanischem Eichhörnchen.\nBenötigt Klassische Ingenieurskunst (75)\nVerkaufspreis:\nKasten mit mechanischem Eichhörnchen\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nErschafft ein mechanisches Eichhörnchen, das Euch folgt. Mit Rechtsklick Euer Eichhörnchen beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:\nHandelspostenpreis: 111Händlerdevisen\nBenötigt Eine Handvoll Kupferbolzen , Kupferbarren , Malachit (2)" }
entries[4409] = { ["name"] = "Bauplan: Kleine Zephyriumladung", ["text"] = "Benutzen: Lehrt Euch die Herstellung einer kleinen Zephyriumladung.\nEine kleine Zephyriumladung, die ausreicht, um einige Türen aufzusprengen.\nBenötigt Klassische Ingenieurskunst (100)\nVerkaufspreis:\nKleine Zephyriumladung\nBenutzen: Sprengt einfache verschlossene Türen und Truhen auf.\nBenötigt Klassische Ingenieurskunst (100)\nVerkaufspreis:\nBenötigt Grobes Sprengpulver (2), Leichtes Leder , Erfrischendes Quellwasser" }
entries[4410] = { ["name"] = "Bauplan: Schattenschutzbrille", ["text"] = "Benutzen: Lehrt Euch die Herstellung einer Schattenschutzbrille.\nBenötigt Klassische Ingenieurskunst (120)\nVerkaufspreis:\nSchattenschutzbrille\nWird beim Anlegen gebunden\nKopf Stoff\n2 Rüstung\n+3 Intelligenz\n+ 6 Vielseitigkeit\nHaltbarkeit 60 / 60\nBenötigt Klassische Ingenieurskunst (1)\nVerkaufspreis:\nBenötigt Mittleres Leder (4), Schattenedelstein (2)\nOptionale Reagenzien: [] (#31)" }
entries[4411] = { ["name"] = "Bauplan: Flammendeflektor", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines Flammendeflektors.\nBenötigt Klassische Ingenieurskunst (125)\nVerkaufspreis:\nFlammendeflektor\nBenutzen: Absorbiert 240 Feuerschaden. Hält 1 Min. lang an. (15 Min Abklingzeit)\n5 Aufladungen\nVerkaufspreis:\nBenötigt Surrendes bronzenes Dingsda , Kleiner Flammenbeutel" }
entries[4412] = { ["name"] = "Bauplan: Mondsichtgewehr", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines Mondsichtgewehrs.\nBenötigt Klassische Ingenieurskunst (145)\nVerkaufspreis:\nMondsichtgewehr\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n4 - 8 Schaden Geschwindigkeit 3.00\n(2.0 Schaden pro Sekunde)\n+3 Beweglichkeit\n+4 Ausdauer\nHaltbarkeit 85 / 85\nVerkaufspreis:\nBenötigt Bronzeröhre (3), Surrendes bronzenes Dingsda (3), Schwerer Griff , Geringer Mondstein (2)\nOptionale Reagenzien: [] (#47)" }
entries[4413] = { ["name"] = "Bauplan: Diskombobulatorstrahl", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines Diskombobulatorstrahls.\nBenötigt Klassische Ingenieurskunst (160)\nVerkaufspreis:\nDiskombobulatorstrahl\nBenutzen: Verwandelt das Ziel in einen Lepragnom und verringert 12 Sek. lang seinen Nahkampfschaden und seine Zaubermacht um 14 sowie seine Bewegungsgeschwindigkeit um 7 %. (1 Min Abklingzeit)\n5 Aufladungen\nVerkaufspreis:\nBenötigt Surrendes bronzenes Dingsda (3), Seidenstoff (2), Jade , Bronzeröhre" }
entries[4414] = { ["name"] = "Bauplan: Tragbarer bronzener Mörser", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines tragbaren bronzenen Mörsers.\nBenötigt Klassische Ingenieurskunst (165)\nVerkaufspreis:\nTragbarer bronzener Mörser\nBenutzen: Fügt Ziele innerhalb von 5 Metern 4 Feuerschaden zu und macht sie 2 Sek. lang handlungsunfähig. Jeglicher Schaden bricht den Effekt ab. Unzuverlässig gegen Ziele über Stufe 49. (1 Min Abklingzeit)\n8 Aufladungen\nBenötigt Klassische Ingenieurskunst (165)\nVerkaufspreis:\nBenötigt Bronzeröhre (4), Eisenstrebe , Schweres Sprengpulver (4), Mittleres Leder (4)" }
entries[4415] = { ["name"] = "Bauplan: Handwerkermonokel", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines Handwerkermonokels.\nBenötigt Klassische Ingenieurskunst (185)\nVerkaufspreis:\nHandwerkermonokel\nWird beim Anlegen gebunden\nKopf Stoff\n2 Rüstung\n+6 Intelligenz\nHaltbarkeit 70 / 70\nBenötigt Klassische Ingenieurskunst (1)\nVerkaufspreis:\nBenötigt Schweres Leder (6), Citrin (2)\nOptionale Reagenzien: [] (#47)" }
entries[4416] = { ["name"] = "Bauplan: Goblinlandmine", ["text"] = "Benutzen: Lehrt Euch die Herstellung einer Goblinlandmine.\nEine Goblinlandmine bauen.\nBenötigt Klassische Ingenieurskunst (195)\nVerkaufspreis:\nGoblinlandmine\nBenutzen: Platziert die Goblinlandmine auf dem Boden. Sie explodiert, sobald eine feindliche Kreatur an ihr vorbeigeht, und fügt ihr 24 Feuerschaden zu. Die Mine ist 1 Min. lang aktiv. (1 Min Abklingzeit)\nBenötigt Klassische Ingenieurskunst (195)\nVerkaufspreis:\nBenötigt Schweres Sprengpulver (3), Eisenbarren (2), Gyrochronatom" }
entries[4417] = { ["name"] = "Bauplan: Große Zephyriumladung", ["text"] = "Benutzen: Lehrt Euch die Herstellung einer großen Zephyriumladung.\nBenötigt Klassische Ingenieurskunst (200)\nVerkaufspreis:\nGroße Zephyriumladung\nBenutzen: Sprengt schwere verschlossene Türen und Truhen auf.\nBenötigt Klassische Ingenieurskunst (200)\nVerkaufspreis:\nBenötigt Robustes Sprengpulver (2), Schweres Leder (2), Erfrischendes Quellwasser" }
